$ErrorActionPreference='Stop'
# Existing original seed only. No visible desktop, clipboard, global input or seed generation.
function Assert-PlainPath([string]$Path) {
 if(-not [IO.Path]::IsPathRooted($Path)){throw 'An absolute path is required'}
 $current=[IO.Path]::GetFullPath($Path)
 while($current){
  if(Test-Path -LiteralPath $current){if(([IO.File]::GetAttributes($current) -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw 'Reparse path rejected'}}
  $next=[IO.Path]::GetDirectoryName($current);if($next -eq $current){break};$current=$next
 }
}
function Assert-Hash([string]$Path,[string]$Expected){
 Assert-PlainPath $Path
 if($Expected -notmatch '^[a-fA-F0-9]{64}$' -or (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash -ne $Expected){throw 'Immutable input hash mismatch'}
}
function Private-Directory([string]$Path){
 Assert-PlainPath $Path
 if(Test-Path -LiteralPath $Path){throw 'Fresh directory required'}
 $sid=[Security.Principal.WindowsIdentity]::GetCurrent().User
 $acl=New-Object Security.AccessControl.DirectorySecurity
 $acl.SetOwner($sid);$acl.SetAccessRuleProtection($true,$false)
 $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($sid,'FullControl','ContainerInherit,ObjectInherit','None','Allow')))
 (New-Object IO.DirectoryInfo($Path)).Create($acl)
}
Assert-Hash $Binary $ExpectedBinarySha
Assert-PlainPath $SeedManifest
if((Get-Item -LiteralPath $SeedManifest).Length -gt 16384){throw 'Seed manifest bound'}
$seed=Get-Content -LiteralPath $SeedManifest -Raw|ConvertFrom-Json
if($seed.version -ne 1 -or $seed.expected -notin @('recovered','pending','error')){throw 'Seed contract invalid'}
$root=[IO.Path]::GetFullPath($seed.owned_root)
$temp=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\')+'\'
if(-not $root.StartsWith($temp,[StringComparison]::OrdinalIgnoreCase)){throw 'Owned temporary root required'}
foreach($key in @('owned_root','appdata','library','source','sentinel','cookie_owner')){
 $path=[IO.Path]::GetFullPath($seed.$key);Assert-PlainPath $path
 if($key -ne 'owned_root' -and -not $path.StartsWith($root.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Seed path outside owned root'}
}
$cookieCache=[IO.Path]::GetFullPath((Join-Path $seed.appdata 'session-cookies')).TrimEnd('\')+'\'
if(-not ([IO.Path]::GetFullPath($seed.cookie_owner)).StartsWith($cookieCache,[StringComparison]::OrdinalIgnoreCase)){throw 'Owner must be under original appdata session-cookies'}
Assert-Hash $seed.source $seed.source_sha256
Assert-Hash $seed.sentinel $seed.sentinel_sha256
if(-not (Test-Path -LiteralPath $seed.appdata -PathType Container) -or -not (Test-Path -LiteralPath $seed.library -PathType Container) -or -not (Test-Path -LiteralPath $seed.cookie_owner -PathType Container)){throw 'Original seed folders required'}
function Snapshot-Owner {
 $rows=@();$total=0
 foreach($file in @(Get-ChildItem -LiteralPath $seed.cookie_owner -Recurse -Force -File)){
  Assert-PlainPath $file.FullName
  $total+=$file.Length;if($rows.Count -ge 32 -or $file.Length -gt 1048576 -or $total -gt 2097152){throw 'Owner manifest bounds'}
  $rows+=@{path=$file.FullName;size=$file.Length;sha=(Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash}
 }
 if($rows.Count -eq 0){throw 'Original owner files required'}
 return $rows
}
$before=@(Snapshot-Owner)
$calls=Join-Path $root 'calls.jsonl';$callsBefore=if(Test-Path -LiteralPath $calls){(Get-FileHash -LiteralPath $calls -Algorithm SHA256).Hash}else{$null}
Private-Directory $OutputDirectory
$before|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $OutputDirectory 'owner-before.json') -Encoding UTF8
$env:DLPAD_TEST_DATA=$seed.appdata;$env:DLPAD_LIBRARY_ROOT=$seed.library
foreach($key in @('DLPAD_YTDLP','DLPAD_GUARDIAN_BACKEND','DLPAD_TEST_SYSTEMD_BUS_PATH','DLPAD_TEST_SYSTEMD_STARTUP_FAULT','DLPAD_TEST_GUARDIAN_EXECUTABLE')){[Environment]::SetEnvironmentVariable($key,$null,'Process')}
