'@
$result=$null
try{
 $result=[CookieStartupGui]::Run($Binary,$root,$OutputDirectory,$seed.expected)|ConvertFrom-Json
 Assert-Hash $Binary $ExpectedBinarySha
 Assert-Hash $seed.source $seed.source_sha256;Assert-Hash $seed.sentinel $seed.sentinel_sha256
 if($seed.expected -eq 'recovered'){
  if(Test-Path -LiteralPath $seed.cookie_owner){throw 'Original completed cookie owner not removed'}
 }else{
  foreach($row in $before){Assert-Hash $row.path $row.sha;if((Get-Item -LiteralPath $row.path).Length -ne $row.size){throw 'Preserved owner size mismatch'}}
  if(@(Snapshot-Owner).Count -ne $before.Count){throw 'Preserved owner file count mismatch'}
 }
 $callsAfter=if(Test-Path -LiteralPath $calls){(Get-FileHash -LiteralPath $calls -Algorithm SHA256).Hash}else{$null}
 if($callsBefore -ne $callsAfter){throw 'Startup invoked synthetic download tool'}
 $result|Add-Member -NotePropertyName original_owner_result_verified -NotePropertyValue $true
 $result|Add-Member -NotePropertyName source_foreign_preserved -NotePropertyValue $true
 $result|Add-Member -NotePropertyName binary_sha256 -NotePropertyValue $ExpectedBinarySha
 if($result.status -ne 'PASS'){throw 'Private startup GUI failed'}
 $result|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $OutputDirectory 'result.json') -Encoding UTF8
}catch{
 @{status='FAIL';error=$_.Exception.Message;runtime_result=$result}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $OutputDirectory 'result.json') -Encoding UTF8
 throw
}
Write-Output ($result|ConvertTo-Json -Depth 8)
